"""Internal type aliases for the hooks runtime."""

from __future__ import annotations

from typing import Literal

from rasa.mantle.hooks.exceptions import HookRejection, RetryModel

HookLane = Literal["observe", "modify"]
FailPolicy = Literal["open", "closed"]
HookOutcome = Literal["success", "timeout", "error", "rejection", "retry"]

ControlSignal = type[HookRejection] | type[RetryModel]

OUTCOME_SUCCESS: HookOutcome = "success"
OUTCOME_TIMEOUT: HookOutcome = "timeout"
OUTCOME_ERROR: HookOutcome = "error"
OUTCOME_REJECTION: HookOutcome = "rejection"
OUTCOME_RETRY: HookOutcome = "retry"

OBSERVE_LANE: HookLane = "observe"
MODIFY_LANE: HookLane = "modify"

OPEN_POLICY: FailPolicy = "open"
CLOSED_POLICY: FailPolicy = "closed"
